INSERT INTO public."Entry" (id, "entryNumber", "beanName", "drinkLabel", title, "cafeName", "roasterName", "dateTried", city, "countryWhereDrank", "originCountry", "originRegion", producer, farm, varietal, process, "tastingNotesRaw", "servedStyle", "personalTastingNote", "whatLingered", "roomNote", "selectionSource", "selectedBy", "curationNote", "memoryNote", "memoryTrip", "turningPoint", "quietFavorite", "wouldRevisit", "postStatus", "photoReadiness", "sourceType", confidence, "createdAt", "updatedAt") VALUES ('cmqdijtn30000iwpk6anzyr8s', NULL, 'Finca Milan Nitro', 'Filter Coffee', NULL, 'Holistic Coffee', NULL, '2026-04-21 00:00:00', 'Hong Kong', 'China', 'Colombia', 'Risaralda', NULL, NULL, 'Caturra', 'Nitro Wash', 'Watermelon, Guava, Muskmelon, Milk Tea', NULL, 'This cup felt immediately more expressive — vivid watermelon followed by a softer muskmelon sweetness, making it feel almost juice-like.', 'The brightness softened as it settled, becoming rounder, creamier, and more drawn out at the finish.', 'Warm, wooden interior matched by the barista''s warm friendliness. ', NULL, NULL, NULL, 'A coffee tasting trip before visiting M+ Museum in West Kowloon', false, false, false, false, 'NOT_PLANNED', 'NO_PHOTOS', 'CURRENT_CUP', 'MEDIUM', '2026-06-14 08:19:29.103', '2026-06-16 13:00:47.398');
